  if(/Изменить состав|Разделить рейс|Разделить склады/i.test(action))return window.openRouteComposer?.(routeId);
  if(/Открыть заказ/i.test(action)){const order=def?.orders?.[0];return order&&window.openDetails?.(order.id)}
